import test from 'node:test';
import assert from 'node:assert/strict';
import { PreviewSession } from '../../core/preview/session.js';
import { CaptureClassification } from '../../core/preview/classification.js';
import { TextProvider,CallBudget,type ModelDeclaration } from '../../core/models/provider.js';
const png='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=';
// Actual 2x2 canvas PNGs generated by disposable Chromium, not native proof.
const red='iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEklEQVR4AWL6z8DwH4SZGKAAAAAA//8qMqaOAAAABklEQVQDADYSBAFv606fAAAAAElFTkSuQmCC';
const blue='iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAE0lEQVR4AWJiYPj/H4SBDAYwAAAAAP//rlr/fgAAAAZJREFUAwAyFgQB54BxFAAAAABJRU5ErkJggg==';
const model:ModelDeclaration={provider:'nebius',id:'invented-vision',text:true,jsonObject:true,inputContextTokens:16384,maxOutputTokens:512,images:{inputTokensUpperBound:4096,accounting:'input-tokens'},pricing:{inputUsdPerMillion:1,outputUsdPerMillion:2,verifiedAt:'2026-10-24',source:'https://example.org/synthetic-pricing'}};
const response=()=>Response.json({choices:[{finish_reason:'stop',message:{role:'assistant',content:JSON.stringify({decision:'suggest',categoryId:'work',activityId:'coding',relatedIds:[]})}}],usage:{prompt_tokens:100,completion_tokens:10}});
function captured(rich=false,provider?:TextProvider){
 const session=new PreviewSession(),classification=new CaptureClassification(session,provider);classification.local(true);
 session.start({rich,retain:rich,pixels:rich});session.focus({epoch:session.epoch,revision:1,at:0,key:'invented-window',app:'spindlefixture',title:'Invented coding article',clock:'invented',browser:false});
 session.sample({epoch:session.epoch,revision:1,at:1,text:'function inventedExample() { return 1; }',status:'native-text',image:rich?png:''});
 return {session,classification,id:session.active!.id};
}
test('disabled local processing does not read captured text even for synchronization',()=>{
 const {session,classification}=captured();classification.local(false);const v=session.active!;let reads=0;const text=v.text;
 Object.defineProperty(v,'text',{get:()=>{reads++;return text;},configurable:true});classification.sync();assert.equal(reads,0);
});
test('local projection and denied image egress do not read captured pixels',async()=>{
 const provider=new TextProvider(model,new CallBudget(1,4),async()=>'invented-key',async()=>response());const {session,classification,id}=captured(true,provider);let reads=0;const v=session.active!,image=v.image;
 Object.defineProperty(v,'image',{get:()=>{reads++;return image;},configurable:true});classification.sync();assert.equal(reads,0);classification.grantRemote(true,false);assert.equal((await classification.classify(id,'image')).status,'FIELDS_DENIED');assert.equal(reads,0);
});
test('actual capture owner supplies identical Basic/Rich local text labels; Clear erases downstream copies without waiting for polling',()=>{
 for(const rich of [false,true]){
  const {session,classification,id}=captured(rich);const assignment=classification.snapshot().assignments[0];assert.equal(assignment.labels.activityId,'coding');
  session.clear();assert.throws(()=>classification.inspect(id),/CONTEXT_UNAVAILABLE/);assert.equal(classification.snapshot().assignments.length,0);
 }
});
test('Rich sends actual matching captured PNG and text; Basic sends no pixels despite vision capability',async()=>{
 const bodies:string[]=[];const provider=new TextProvider(model,new CallBudget(1,4),async()=>'invented-key',async(_u,r)=>{bodies.push(String(r?.body));return response();});
 for(const rich of [false,true]){
  const {classification,id}=captured(rich,provider);classification.grantRemote(true,rich);
  assert.equal((await classification.classify(id,rich?'image':'text')).status,'suggested');
 }
 assert.equal(typeof JSON.parse(bodies[0]).messages[1].content,'string');assert.ok(!bodies[0].includes(png));
 const content=JSON.parse(bodies[1]).messages[1].content;assert.ok(content[0].text.includes('inventedExample'));assert.equal(content[1].image_url.url,'data:image/png;base64,'+png);
});
test('remote image requires explicit image grant; missing image never silently downgrades',async()=>{
 let reads=0;const provider=new TextProvider(model,new CallBudget(1,4),async()=>{reads++;return 'invented-key';},async()=>response());
 const rich=captured(true,provider);rich.classification.grantRemote(true,false);assert.equal((await rich.classification.classify(rich.id,'image')).status,'FIELDS_DENIED');assert.equal(reads,0);
 const basic=captured(false,provider);basic.classification.grantRemote(true,true);assert.equal((await basic.classification.classify(basic.id,'image')).status,'IMAGE_UNAVAILABLE');assert.equal(reads,0);
});
test('capture Pause/Clear and remote revoke reject late image results',async()=>{
 for(const action of ['pause','clear','remote'] as const){
  let release!:(r:Response)=>void,entered!:()=>void;const started=new Promise<void>(r=>{entered=r;});
  const provider=new TextProvider(model,new CallBudget(1,4),async()=>'invented-key',async()=>{entered();return new Promise<Response>(r=>{release=r;});});
  const {session,classification,id}=captured(true,provider);classification.grantRemote(true,true);const pending=classification.classify(id,'image');await started;
  if(action==='pause')session.pause(2);else if(action==='clear')session.clear();else classification.revokeRemote();release(response());
  assert.ok(['STALE_RESULT','TIMEOUT_OR_CANCELLED'].includes((await pending).status));
  if(action==='clear')assert.equal(classification.snapshot().assignments.length,0);else assert.notEqual(classification.inspect(id).labels.categoryId,'work');
 }
});
test('Rich can classify an admitted image when OCR/text are empty, without inventing text',async()=>{
 const bodies:string[]=[];const provider=new TextProvider(model,new CallBudget(1,4),async()=>'invented-key',async(_u,r)=>{bodies.push(String(r?.body));return response();});
 const {session,classification,id}=captured(true,provider);session.active!.title='';session.sample({epoch:session.epoch,revision:1,at:2,text:'',status:'pixel-window-readback',image:png});classification.grantRemote(true,true);
 assert.equal((await classification.classify(id,'image')).status,'suggested');assert.equal(bodies.length,1);assert.equal(JSON.parse(bodies[0]).messages[1].content[1].image_url.url,'data:image/png;base64,'+png);
});
test('Windows independent OCR/image outcomes preserve usable evidence without admitting failed pixels',async()=>{
 for(const ocr of ['ocr-empty','ocr-failed','ocr-engine-unavailable','ocr-language-unavailable']){
  let calls=0;const provider=new TextProvider(model,new CallBudget(1,3),async()=>'invented-key',async()=>{calls++;return response();});
  const {session,classification,id}=captured(true,provider);classification.grantRemote(true,true);
  const capture={pixels:'captured',ocr,image:'image-retained',sourceWidth:1,sourceHeight:1,imageWidth:1,imageHeight:1,ocrWidth:1,ocrHeight:1};
  session.sample({epoch:session.epoch,revision:1,at:2,text:'',textSource:'ocr',status:ocr,image:png,capture});
  assert.equal((await classification.classify(id,'image')).status,'suggested');assert.equal(calls,1);
  session.sample({epoch:session.epoch,revision:1,at:3,text:'',status:'pixels-window-changed',image:'',capture:{...capture,pixels:'pixels-window-changed'}});
  assert.throws(()=>classification.inspect(id),/CONTEXT_UNAVAILABLE/);assert.equal(calls,1);
 }
 for(const ocr of ['local-ocr','ocr-not-requested']){
  const {session,classification,id}=captured(true);
  session.sample({epoch:session.epoch,revision:1,at:2,text:'function preservedText() { return 1; }',textSource:ocr==='local-ocr'?'ocr':'native',status:'image-encode-failed',image:'',capture:{pixels:'captured',ocr,image:'image-encode-failed',sourceWidth:1,sourceHeight:1,imageWidth:0,imageHeight:0,ocrWidth:1,ocrHeight:1}});
  assert.equal(classification.inspect(id).labels.activityId,'coding');
 }
});

test('changed captured evidence rejects a stale correction rather than applying it to new content',()=>{
 const {session,classification,id}=captured();const old=classification.snapshot().assignments[0].ref;
 session.sample({epoch:session.epoch,revision:1,at:2,text:'function differentExample() { return 2; }',status:'native-text'});
 assert.throws(()=>classification.correct(id,{categoryId:'learning',activityId:'reading',relatedIds:[]},old),/STALE_EVIDENCE/);
});
test('browser revoke scrubs labels while local processing is off; re-admission has a new context identity',()=>{
 const session=new PreviewSession(),classification=new CaptureClassification(session);classification.local(true);session.start({pixels:false,rich:false,retain:false});session.focus({epoch:session.epoch,revision:1,at:0,key:'invented-browser',app:'chrome',title:'SUPPRESSED',clock:'invented',browser:true});
 const context=()=>({challenge:session.challenge(),private:false,focused:true,document:'invented-document',url:'https://example.org',title:'Invented article',text:'function inventedBrowserExample() { return 1; }'});
 assert.equal(session.browser(context()),true);const old=classification.snapshot().assignments[0];classification.local(false);session.revokeBrowser();classification.local(true);assert.equal(classification.snapshot().assignments.length,0);assert.equal(session.browser(context()),true);const fresh=classification.snapshot().assignments[0];assert.notEqual(fresh.ref.recordingId,old.ref.recordingId);assert.equal(fresh.ref.visitId,old.ref.visitId);
});
test('changed/removed captured image invalidates completed image labels and exact-image corrections',async()=>{
 const provider=new TextProvider(model,new CallBudget(1,4),async()=>'invented-key',async()=>response());
 const {session,classification,id}=captured(true,provider);session.sample({epoch:session.epoch,revision:1,at:2,text:'',status:'pixel-window-readback',image:red});classification.grantRemote(false,true);
 assert.equal((await classification.classify(id,'image')).status,'suggested');const old=classification.inspect(id).ref;
 session.sample({epoch:session.epoch,revision:1,at:3,text:'',status:'pixel-window-readback',image:blue});
 assert.notEqual(classification.inspect(id).labels.categoryId,'work');assert.ok(classification.inspect(id).ref.evidenceRevision>old.evidenceRevision);
 assert.throws(()=>classification.correct(id,{categoryId:'learning',activityId:'reading',relatedIds:[]},old),/STALE_EVIDENCE/);
 const beforeRemoval=classification.inspect(id).ref;session.sample({epoch:session.epoch,revision:1,at:4,text:'',status:'pixel-window-readback',image:''});
 assert.throws(()=>classification.correct(id,{categoryId:'learning',activityId:'reading',relatedIds:[]},beforeRemoval),/STALE_EVIDENCE/);
});
test('an unrelated visit update preserves completed and pending selected-visit model labels',async()=>{
 for(const pending of [false,true]){
  let release!:(r:Response)=>void,entered!:()=>void;const started=new Promise<void>(r=>{entered=r;});
  const provider=new TextProvider(model,new CallBudget(1,4),async()=>'invented-key',async()=>{entered();return pending?new Promise<Response>(r=>{release=r;}):response();});
  const {session,classification,id}=captured(false,provider);session.focus({epoch:session.epoch,revision:2,at:3,key:'second-window',app:'spindlefixture',title:'Invented second article',clock:'invented',browser:false});session.sample({epoch:session.epoch,revision:2,at:4,text:'Other invented content before update',status:'native-text'});classification.grantRemote(true,false);
  const result=classification.classify(id,'text');await started;if(!pending)assert.equal((await result).status,'suggested');
  session.sample({epoch:session.epoch,revision:2,at:5,text:'Other invented content after update',status:'native-text'});
  if(pending){release(response());assert.equal((await result).status,'suggested');}
  assert.equal(classification.inspect(id).labels.categoryId,'work');
 }
});
test('image replacement still rejects an older in-flight image result',async()=>{
 let release!:(r:Response)=>void,entered!:()=>void;const started=new Promise<void>(r=>{entered=r;});const provider=new TextProvider(model,new CallBudget(1,4),async()=>'invented-key',async()=>{entered();return new Promise<Response>(r=>{release=r;});});
 const {session,classification,id}=captured(true,provider);classification.grantRemote(true,true);const result=classification.classify(id,'image');await started;session.sample({epoch:session.epoch,revision:1,at:2,text:'function inventedExample() { return 1; }',status:'pixel-window-readback',image:blue});release(response());assert.ok(['STALE_RESULT','TIMEOUT_OR_CANCELLED'].includes((await result).status));
});
test('late-sampled gap context is removed from the downstream classifier',()=>{
 const {session,classification,id}=captured(true);classification.snapshot();session.gap(0.5);assert.equal(session.visits[0].image,'');assert.throws(()=>classification.inspect(id),/CONTEXT_UNAVAILABLE/);assert.equal(classification.snapshot().assignments.length,0);
});
test('manual correction wins without spending or transmitting an image',async()=>{
 let requests=0;const provider=new TextProvider(model,new CallBudget(1,4),async()=>{requests++;return 'invented-key';},async()=>response());
 const {classification,id}=captured(true,provider);classification.grantRemote(true,true);classification.correct(id,{categoryId:'learning',activityId:'reading',relatedIds:[]});
 assert.equal((await classification.classify(id,'image')).status,'user-choice-preserved');assert.equal(requests,0);assert.equal(classification.inspect(id).labels.categoryId,'learning');
});
